#!/bin/bash
# Regenerate the Swift, Kotlin and TypeScript wire types from the Rust view models (ov-1035).
#
# The shared views (the plan, its column, the workflow runs) are built in Rust and cross the
# C, JNI and wasm bridges as JSON. The types the apps decode that JSON into are generated
# from the `#[typeshare]` types in crates/client and crates/workflow, so a field is added in
# Rust once and the three decoders cannot drift from it.
#
#   scripts/gen-wire-types.sh          rewrite the three generated files
#   scripts/gen-wire-types.sh --check  fail, naming the file, if any is out of date
#
# CI runs --check. The CLI is pinned: another version words its output differently.
set -euo pipefail
cd "$(dirname "$0")/.."

PINNED=1.13.4
SWIFT=apps/shared/AgentKit/Sources/AgentKit/Generated/WireTypes.swift
KOTLIN=apps/android/app/src/main/java/com/farcooler/core/wire/WireTypes.kt
TS=services/web/src/client/generated/wire-types.ts

if ! command -v typeshare >/dev/null; then
  echo "typeshare $PINNED is not installed: cargo install typeshare-cli --version $PINNED --locked" >&2
  exit 2
fi
have=$(typeshare --version | awk '{print $2}')
if [ "$have" != "$PINNED" ]; then
  echo "typeshare $have is installed; this tree is generated with $PINNED" >&2
  exit 2
fi

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

generate() { # language, output
  typeshare crates/client/src crates/workflow/src --lang="$1" --config-file=typeshare.toml \
    --output-file="$work/raw" >/dev/null 2>&1
  {
    echo "// GENERATED by scripts/gen-wire-types.sh from the #[typeshare] types in crates/. DO NOT EDIT."
    echo "// Change the Rust type and run the script; CI fails on a difference."
    echo
    # typeshare writes Swift properties as `let`; the hand-written structs these replace were `var`,
    # and a screen's tests change one field of a decoded value.
    if [ "$1" = swift ]; then sed 's/^\tpublic let /\tpublic var /' "$work/raw"; else cat "$work/raw"; fi
  } >"$work/$2"
}

generate swift swift
generate kotlin kotlin
generate typescript ts

status=0
install_one() { # generated, destination
  if [ "${MODE:-write}" = check ]; then
    if ! cmp -s "$work/$1" "$2"; then
      echo "$2 is out of date: run scripts/gen-wire-types.sh" >&2
      status=1
    fi
  else
    mkdir -p "$(dirname "$2")"
    cp "$work/$1" "$2"
  fi
}
[ "${1:-}" = "--check" ] && MODE=check
install_one swift "$SWIFT"
install_one kotlin "$KOTLIN"
install_one ts "$TS"
exit $status
